                i += 3
            else:
                i += 1
        if not (10 <= len(cols) <= 14):
            continue
        r.shuffle(cols)
        nf = r.randint(5, min(8, len(cols) - 4))
        nt = len(cols) - nf
        if not (4 <= nt <= 7):
            continue
        g = ["_"] * W
        for c in cols[:nf]:
            g[c] = "*"
        for c in cols[nf:]:
            g[c] = "Y"
