def blocks(p):
    return [m.span() for m in re.finditer("1+", p)]

def paint(W, B):
    p = ["0"] * W
    for x, y in B:
        for i in range(x, y):
            p[i] = "1"
    return "".join(p)

def facts(g, p):
    W = len(g); R = blocks(p); ed = set(); ins = set(); ou = set()
    for x, y in R:
        ed |= {i for i in (x - 1, y) if 0 <= i < W}
        ins |= {x, y - 1}
        ou |= {i for i in (x - 2, y + 1) if 0 <= i < W and p[i] == "0"}
    F = []; G = [0, 0, 0, 0]
    for ch in "*Y":
        P = [i for i, q in enumerate(g) if q == ch]
        w = [i for i in P if p[i] == "1"]
        F.append([len(w), len(P) - len(w), len([i for i in P if i in ins]),
                  len([i for i in P if (i and p[i-1] == "1") or (i+1 < W and p[i+1] == "1")]),
                  len([1 for x, y in R if [1 for i in P if x <= i < y]]),
                  len([i for i in P if i in ou])])
        G[0] += len([i for i in P if i in ins])
        G[1] += len([i for i in P if i in ou])
        G[2] += len([i for i in w if i not in ins])
        G[3] += len([i for i in P if i not in ed and i not in ou and p[i] == "0"])
    E = [g[i] for x, y in R for i in (x - 1, y) if 0 <= i < W]
    c = (E.count("*"), E.count("Y"))
    A = [len(R), len(R) - 1, max([y - x for x, y in R] or [0]), F[0][0] + F[1][0], c[0] + c[1]]
    idle = len([1 for x, y in R if not [1 for i in (x-1, y) if 0 <= i < W and g[i] in "*Y"]])
    return F, A, G, idle, c

def bad(g, p, a, b):
    F, A, G, idle, c = facts(g, p)
    v = len([1 for x in F[0] if x == a]) + len([1 for x in F[1] if x == b])
    return v + len([1 for x in A if x in (a, b)]) + len([1 for x in G if x < 1]) + (idle < 1)

def build(rng, g, a, b, pr):
    W = len(g)
    fl = [i for i, q in enumerate(g) if q == "*"]
    tr = [i for i, q in enumerate(g) if q == "Y"]
    tg = set(rng.sample(fl, a) + rng.sample(tr, b))
    keep = set()
    if pr:
        for P in (fl, tr):
            o = [i for i in P if i not in tg]
            if o: keep.add(rng.choice(o))
    rest = [i for i in fl + tr if i not in tg and i not in keep] or [rng.randrange(W)]
    B = []
    def fits(x, y, skip=-1):
        if x < 0 or y > W or y - x < 3: return False
        for j, (u, v) in enumerate(B):
            if j != skip and not (y + 2 <= u or v + 2 <= x): return False
        if [1 for t in tg if x <= t < y]: return False
        if [1 for q in keep if x - 3 < q < y + 3]: return False
        for i in (x - 1, y):
            if 0 <= i < W and g[i] in "*Y" and i not in tg: return False
        return True
    order = sorted(tg); rng.shuffle(order)
    for t in order:
        if [1 for x, y in B if t in (x - 1, y)]: continue
        for _ in range(16):
            w = rng.randint(3, 8)
            x = t + 1 if rng.random() < 0.5 else t - w
            if fits(x, x + w):
                B.append((x, x + w)); break
        else:
            return None
    fixed = len(B)
    def anchor():
        w = rng.randint(3, 9); q = rng.choice(rest); m = rng.random()
        if m < 0.22: x = q
        elif m < 0.42: x = q - w + 1
        elif m < 0.56: x = q + 2
        elif m < 0.70: x = q - w - 2
        else: x = rng.randrange(0, max(1, W - 2))
        return x, x + w
    for _ in range(rng.randint(1, 4)):
        for _ in range(16):
            x, y = anchor()
            if fits(x, y):
                B.append((x, y)); break
    if len(B) < 2: return None
    v = bad(g, paint(W, B), a, b)
    for _ in range(420):
        if not v: break
        C = list(B); m = rng.random()
        if m < 0.42 or len(C) <= max(2, fixed + 1):
            x, y = anchor()
            if not fits(x, y): continue
            C.append((x, y))
        elif m < 0.72:
            C.pop(rng.randrange(fixed, len(C)))
        else:
            j = rng.randrange(fixed, len(C)); x, y = anchor()
            old = B; B = C; ok = fits(x, y, skip=j); B = old
            if not ok: continue
            C[j] = (x, y)
        if len(C) < 2: continue
        w = bad(g, paint(W, C), a, b)
        if w <= v: B, v = C, w
    return paint(W, B), v

def render(rng, g, p):
    rain = rng.choice(("|", "|", "/", "'"))
    top = rng.choice(("#", "#", rain))
    dry = rng.choice((" ", " ", "."))
    return "\n".join(["".join((top if i == 0 else rain) if q == "1" else dry
                              for q in p).rstrip() for i in range(rng.choice((2, 3, 3, 4)))] + [g])

def solve(clue):
    g, k = clue.split("/")
    a, b = int(k[1]), int(k[3])
    rng = random.Random(clue)
    best = None
    for n in range(70):
        out = build(rng, g, a, b, n < 62)
        if out is None: continue
        p, v = out
        R = blocks(p)
        if len(R) < 2 or [1 for x, y in R if y - x < 3]: continue
        if [1 for i in range(1, len(R)) if R[i][0] - R[i-1][1] < 2]: continue
        if facts(g, p)[4] != (a, b): continue
        if not v: return render(rng, g, p)
        if best is None or v < best[1]: best = (p, v)
    return render(rng, g, best[0]) if best else ""
